<span class="line"><span style="color:#E06C75;font-style:italic;">            egfr</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">patient_data.</span><span style="color:#61AFEF;">get</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;egfr&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;未检测&quot;</span><span style="color:#ABB2BF;">),</span></span>
